"""Offline materials use one audited content file and actual M10 images."""
from pathlib import Path
import json,html
ROOT=Path(__file__).resolve().parents[2];OUT=ROOT/'presentation_demo/m11'

SCENES=[
('Judul dan tujuan',[1,2],'Mulai presentasi. Jelaskan konteks sebelum memutar kendaraan.','Model ini menyediakan ruang diskusi bersama tentang jaringan, kendaraan, sinyal, rel dan pilihan operasional. Kita dapat mengubah tampilan serta membandingkan keluaran simulasi yang sudah dijalankan. Tujuan pertemuan adalah memeriksa apakah representasi dan kebutuhan datanya sesuai pengetahuan lapangan.','Masalah dan pergerakan mana yang perlu kita prioritaskan?'),
('Gambaran geografis',[3],'Pilih aerial, lalu overlay Jalan utama / frontage.','Perhatikan koridor utama, frontage yang terpisah, feeder, simpang, Ketajen dan perlintasan. Jaringan mengikuti geometri SUMO dari sumber geospasial. Bangunan dan vegetasi membantu orientasi visual, tetapi belum mewakili bangunan fisik yang disurvei. Tujuh titik observasi masih berupa calon lokasi.','Akses, arah atau titik pertemuan mana yang perlu dikoreksi?'),
('Jaringan dan kelas kendaraan',[4,5],'Pilih main atau reverse. Buka Analisis & filter, pilih kendaraan aktif lalu Ikuti pilihan.','Motor, mobil, pickup/van, minibus, bus dan beberapa ukuran truk memiliki dimensi serta kelas model. Yang bergerak di layar mengikuti posisi keluaran SUMO, bukan animasi kendaraan acak. Kita belum mengukur komposisi armada Gedangan. Menampilkan trailer tidak membuktikan clearance atau legalitas semua rute fisik.','Apakah klasifikasi kendaraan dan gerakan yang akan dihitung cukup jelas?'),
('Perlintasan kereta',[5,6],'Pilih railway. Tampilkan 105,5 s, putar sebentar, lalu geser ke 160 s.','Kereta dan status penutupan berasal dari event controller yang direkam. Pada jendela model ini kita dapat melihat keadaan jalan ditutup dan kemudian dibuka kembali. Durasi serta sudut palang merupakan representasi model. Jadwal, timing dan posisi fisik palang tetap perlu diverifikasi.','Event awal peringatan, tutup, lewat, clearance dan buka mana yang dapat diamati dengan aman?'),
('Baseline ilustratif 2026',[6,7],'Pilih 2026, REFERENCE, S00. Keluar dari mode terpandu untuk membuka metrik horizon bila diperlukan.','Dalam horizon model 35 menit, ada 240 requested. Sebanyak 206 dapat dirutekan dan berangkat. Sebanyak 183 tiba, 23 masih berjalan dan 34 gagal rute, sementara belum berangkat bernilai nol. Jadi 57 belum tiba saat simulasi berakhir. Jumlah ini adalah hasil demand model dan belum mewakili volume kendaraan lapangan.','Data count dan OD apa yang tersedia untuk mengganti asumsi ini?'),
('Pertumbuhan 2026–2040',[8],'Keluar presentasi terpandu. Pilih TRAFFIC GROWTH dan tahun 2026, 2030, 2035, 2040 dengan S00 / REFERENCE.','Requested pada empat rekaman itu adalah 240, 269, 311 dan 360. Engine memakai pertumbuhan majemuk per kelas dan OD. Sebagai contoh, laju mobil REFERENCE 3,5 persen per tahun. Override motor northbound 4 persen mengganti laju motor umum 2,5 persen. Ini asumsi percobaan perangkat lunak yang belum menjadi prakiraan resmi.','Sumber pertumbuhan, perubahan akses dan perubahan komposisi apa yang perlu diuji?'),
('Indikator antrean dan kemacetan',[9],'Pilih 2040 HIGH S00. Kamera junction, timeline 1687,5 s. Bandingkan overlay berhenti dan occupied length.','Warna kendaraan berhenti berasal dari kecepatan sampel kurang dari 0,3 meter per detik. Occupied length menghitung gabungan panjang badan kendaraan pada lajur. Keduanya berbeda dari antrean meter yang diukur pengamat. Spillback terverifikasi dalam model adalah indikator event sepanjang horizon dan tidak otomatis menjelaskan sebab kemacetan saat ini.','Di mana referensi awal/akhir antrean, batas pandang dan detector harus diverifikasi?'),
('Skenario operasional',[10,12],'Pilih 2026 REFERENCE dan SOLUTIONS, lalu S00 sampai S04. Tunjukkan status S05, S06 dan S07.','Rekaman tersedia untuk baseline, perubahan timing APILL, manajemen akses feeder, frontage dan penjadwalan kendaraan berat. Kombinasi yang belum dijalankan tetap NOT RUN. S05 belum siap simulasi. Flyover dan underpass masih skema konsep tanpa kendaraan, ramp final atau angka efektivitas.','Intervensi operasional mana yang legal, realistis dan layak menjadi hipotesis pengujian?'),
('Perbandingan hasil',[11],'Pilih 2040 HIGH, S01 dan COMPARISON. Gunakan kamera junction dan clock yang sama.','Pada pasangan ini, S00 mencatat 356 tiba dari 500 requested. S01 mencatat 328 tiba dari 500 requested, atau 28 lebih sedikit. Antarmuka menampilkan WORSENED IN THIS SIMULATION untuk jumlah tiba. Kita tetap membaca failed routes, belum berangkat, unfinished trips serta trade-off OD. Perbandingan ini belum membuktikan keberhasilan atau kegagalan kebijakan di lapangan.','Di ruas atau OD mana manfaat dan kerugian model bergeser?'),
('Validasi lapangan dan tindak lanjut',[13,14,15],'Buka FIELD DATA. Kembali ke OVERVIEW, tunjukkan cara mulai ulang, lalu tutup layanan setelah diskusi.','Model dan bahan demonstrasi sudah tersedia. Tahap berikutnya membutuhkan count per kelas dan arah, turning, timing sinyal, event kereta/palang, travel time, antrean serta verifikasi geometri. Kita perlu menyepakati lokasi, izin, metode, penanggung jawab dan QC data. Workbench M08.5 masih menunggu penerimaan browser untuk penggunaan survei.','Siapa meninjau setiap kebutuhan, dan kapan keputusan metode serta lokasi dapat dicatat?'),
]

def main():
 d=json.loads((OUT/'M11_PRESENTATION_CONTENT.json').read_text());a=json.loads((OUT/'M11_NUMERIC_DATA_AUDIT.json').read_text());OUT.mkdir(exist_ok=True)
 for minutes,seconds in [(5,30),(15,90)]:
  text=f'# Naskah presentasi {minutes} menit\n\nTarget waktu, bukan jaminan durasi pembicara. Bahasa utama Indonesia. Pilih mode eksekutif untuk 5 menit dan mode teknis untuk 15 menit. Angka dan rekamannya sama. Rehearsal otomatis menguji waktu/UI, bukan penampilan presenter manusia.\n\n'
  for i,(title,ids,action,narrative,q) in enumerate(SCENES):
   source=' '.join(d['slides'][j-1]['note'] for j in ids)
   start=i*seconds;end=(i+1)*seconds
   text+=f'## {i+1:02d}. {title} ({start//60:02d}:{start%60:02d}–{end//60:02d}:{end%60:02d})\n\n**Tampilan:** slide '+', '.join(map(str,ids))+f'. {action}\n\n**Narasi:** {narrative}\n\n**Pertanyaan diskusi:** {q}\n\n'
   if minutes==15:text+=f'**Pendalaman teknis dan sumber:** {source}\n\n**Cek pemahaman:** bedakan input asumsi, keluaran SUMO dan observasi lapangan. Catat koreksi peserta pada lembar diskusi. Jangan mengubah data di tengah demonstrasi agar hasil terlihat lebih baik. Gunakan sisa jendela adegan untuk menunjukkan kontrol, jeda playback dan meninjau unit serta censoring.\n\n'
   else:text+='**Sumber dan batas:** screenshot/rekaman M10 dari run SUMO M08 dan audit M11. Permintaan, kontrol, dimensi dan pertumbuhan masih asumsi. Baseline 2026 belum terkalibrasi.\n\n'
  text+='## Petunjuk operator\n\nMulai lewat START_PRESENTASI_TEKNIS_GEDANGAN.bat, tunggu verifikasi dan tombol START PRESENTATION aktif. Alur terpandu M10 menyediakan sepuluh bagian. Untuk pertumbuhan lengkap, pilihan skenario dan adverse comparison 2040 HIGH, keluar dari mode terpandu lalu gunakan selector yang sama di aplikasi. Setelah contoh, kembali ke FIELD DATA dan OVERVIEW. Jangan membuka Analisis & filter kecuali diperlukan untuk penjelasan teknis.\n\nBila layanan terputus, buka deck/PDF atau video lokal melalui MULAI_PRESENTASI.html. Slide dan catatan tidak memerlukan server. Presenter manusia, kondisi ruangan dan proyektor fisik tetap HUMAN ACCEPTANCE REQUIRED.\n'
  (OUT/f'M11_NASKAH_PRESENTASI_{minutes}_MENIT.md').write_text(text,encoding='utf-8')
 # Offline deck uses rendered slides plus two levels of notes from the same content JSON.
 pages=[]
 for s in d['slides']:
  simple=' '.join(s['body']);pages.append(f'<section class="slide" data-slide="{s["number"]}"><img src="slides/slide-{s["number"]:02d}.png" alt="{html.escape(s["title"])}"><aside><p class="executive">{html.escape(simple)}</p><p class="technical">{html.escape(s["note"])}</p></aside></section>')
 css='''*{box-sizing:border-box}body{margin:0;background:#122b36;color:#e6eee6;font:18px Arial,sans-serif}header{display:flex;gap:12px;align-items:center;padding:12px 22px;flex-wrap:wrap}header b{margin-right:auto}button,a{background:#cfb16e;color:#193440;border:0;border-radius:5px;padding:10px 16px;font:inherit;text-decoration:none;cursor:pointer}button:focus-visible,a:focus-visible{outline:3px solid white}.slide{display:none}.slide.active{display:block}.slide img{display:block;max-width:100%;max-height:calc(100vh - 155px);margin:auto;object-fit:contain}.slide aside{max-width:1200px;margin:auto;padding:0 22px;font-size:18px;line-height:1.5}.technical{display:none}body.tech .technical{display:block}body.tech .executive{display:none}body.tech img{max-height:65vh}footer{padding:10px 22px;color:#bacdbf}video{max-width:100%}.controls{display:flex;gap:8px;flex-wrap:wrap}@media print{header,aside,footer{display:none}.slide{display:block;page-break-after:always}.slide img{width:100%;max-height:none}}'''
 js="""const slides=[...document.querySelectorAll('.slide')];let i=0;function show(n){i=Math.max(0,Math.min(slides.length-1,n));slides.forEach((s,j)=>s.classList.toggle('active',i===j));document.querySelector('#count').textContent=(i+1)+' / '+slides.length}document.querySelector('#next').onclick=()=>show(i+1);document.querySelector('#prev').onclick=()=>show(i-1);document.querySelector('#mode').onchange=e=>document.body.classList.toggle('tech',e.target.value==='technical');document.querySelector('#full').onclick=async()=>{if(document.fullscreenElement)await document.exitFullscreen();else await document.documentElement.requestFullscreen()};document.addEventListener('keydown',e=>{if(e.target.matches('select,input'))return;if(e.key==='ArrowRight')show(i+1);if(e.key==='ArrowLeft')show(i-1);if(e.key==='Home')show(0)});show(0);"""
 (OUT/'M11_PRESENTASI_OFFLINE.html').write_text('<!doctype html><html lang="id"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Presentasi Teknis Gedangan</title><style>'+css+'</style><header><b>EXTREME STUDIOS / GEDANGAN</b><label>Penjelasan <select id="mode"><option value="executive">Eksekutif</option><option value="technical">Teknis</option></select></label><button id="prev">Sebelumnya</button><span id="count"></span><button id="next">Berikutnya</button><button id="full">Fullscreen</button></header>'+''.join(pages)+'<footer>Simulasi ilustratif. Baseline 2026 belum dikalibrasi secara empiris. Semua aset lokal.</footer><script>'+js+'</script></html>',encoding='utf-8')
 entry='''<!doctype html><html lang="id"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Mulai Presentasi Gedangan</title><style>'''+css+'''main{max-width:1100px;margin:30px auto;padding:25px}h1{font-size:42px;max-width:850px}p{line-height:1.7;color:#c0d2c8}.options{display:grid;grid-template-columns:1fr 1fr;gap:20px;margin:30px 0}.option{border-top:2px solid #b99a55;padding:18px 0}.option a{display:inline-block;margin:5px 5px 5px 0}small{color:#dcc99a}summary{cursor:pointer;padding:15px 0}video{width:100%;background:#000}select{font:inherit;padding:8px} @media(max-width:650px){.options{grid-template-columns:1fr}h1{font-size:30px}}</style><main><small>EXTREME STUDIOS</small><h1>GEDANGAN TRAFFIC SIMULATOR</h1><p>3D Traffic Digital Twin &amp; Scenario Analysis</p><p><b>PRESENTATION-READY ILLUSTRATIVE TRAFFIC SIMULATION</b><br>2026 NOT EMPIRICALLY CALIBRATED</p><div class="options"><section class="option"><h2>Demonstrasi interaktif</h2><p>Launcher memeriksa rekaman dan memakai layanan M10 yang sama. Di aplikasi, tunggu tombol START PRESENTATION aktif. Lima rekaman utama perlu selesai dimuat. Pilihan tahun/skenario lain menampilkan indikator pemuatan sendiri.</p><a href="http://127.0.0.1:5186/visual.html">Buka aplikasi 3D M10</a><p>READY TO PRESENT berarti verifikasi launcher berhasil dan tombol START aktif. Jika aplikasi belum terbuka atau layanan terputus, gunakan bahan offline di samping. Jalankan launcher kembali untuk pemulihan.</p></section><section class="option"><h2>Bahan pertemuan offline</h2><p>Dua tingkat penjelasan memakai angka yang sama. Pilih Eksekutif atau Teknis di deck HTML.</p><a href="M11_PRESENTASI_OFFLINE.html">Deck offline</a><a href="M11_PRESENTASI_TEKNIS_GEDANGAN.pptx">PowerPoint</a><a href="M11_PRESENTASI_TEKNIS_GEDANGAN.pdf">PDF</a><p><a href="M11_NASKAH_PRESENTASI_5_MENIT.md">Naskah 5 menit</a><a href="M11_NASKAH_PRESENTASI_15_MENIT.md">Naskah 15 menit</a></p><p><a href="M11_LEMBAR_DISKUSI_LAPANGAN.pdf">Lembar diskusi</a><a href="M11_LAMPIRAN_TEKNIS.md">Lampiran teknis</a></p></section></div><details><summary>Video cadangan lokal, tetap tersedia saat layanan 3D berhenti</summary><video controls preload="metadata" src="GEDANGAN_3D_DEMO.mp4"></video><p>Rekaman layar actual SUMO playback M10. Tidak ada cuplikan simulasi buatan untuk mengganti hasil.</p></details><h2>Hasil yang perlu dibaca dengan hati-hati</h2><p>2040 HIGH: S00 356 tiba / 500 requested. S01 328 tiba / 500 requested. Hasil jumlah tiba memburuk pada pasangan simulasi ini. Tidak ada kesimpulan efektivitas lapangan atau solusi terbaik otomatis.</p><p>Flyover/underpass tetap konseptual. Geometri dan lokasi survei memerlukan verifikasi. Workbench M08.5 masih menunggu penerimaan browser.</p></main></html>'''
 entry=entry.replace('<div class="options">','<p id="readiness" role="status">STATUS BELUM DIPERIKSA. Jalankan launcher untuk memeriksa rekaman. Bahan offline tetap tersedia.</p><div class="options">')
 entry=entry.replace('href="http://127.0.0.1:5186/visual.html"','id="open3d" href="http://127.0.0.1:5186/visual.html"')
 entry=entry.replace('</body>','') if '</body>' in entry else entry
 entry=entry.replace('</html>','<script src="readiness.js"></script><script>if(window.M11_READINESS){document.getElementById("readiness").textContent=window.M11_READINESS.status+": "+window.M11_READINESS.message;document.getElementById("open3d").href=window.M11_READINESS.app_url}</script></html>')
 (OUT/'MULAI_PRESENTASI.html').write_text(entry,encoding='utf-8')
 plan=a['survey_plan'];table='\n'.join('| '+r['location_id']+' | '+r['direction']+' | '+r['edge_id']+' | BELUM DISETUJUI |'for r in plan)
 checklist='''# Checklist pertemuan lapangan Gedangan

Seluruh lokasi berikut adalah calon titik model. Tidak ada izin, jam puncak, posisi kamera atau keputusan peserta yang diasumsikan telah disetujui.

Tanggal/pertemuan: ____________________  Pihak hadir: ____________________
Pencatat: ____________________  Peninjau keputusan: ____________________

| Calon titik M06/M08.5 | Arah model | Edge model | Status |
|---|---|---|---|
'''+table+'''

## Keputusan yang perlu dicatat

| Topik | Keputusan / koreksi peserta | PIC / tenggat |
|---|---|---|
| Ruas, arah dan gerakan prioritas | ____________________ | ____________________ |
| Reconnaissance dan akses ke calon titik | ____________________ | ____________________ |
| Izin pengamatan/video dan penggunaan data | ____________________ | ____________________ |
| Posisi aman pengamat/kamera dan arah pandang | ____________________ | ____________________ |
| Hari, jam, cuaca dan kejadian khusus | ____________________ | ____________________ |
| Kelas kendaraan dan ambigu/oversize | ____________________ | ____________________ |
| Count 15 menit per kelas/arah/gerakan | ____________________ | ____________________ |
| Turning movement dan metode OD | ____________________ | ____________________ |
| Signal head, fase, cycle, offset, jam acuan | ____________________ | ____________________ |
| Warning, tutup, lintas, clearance, buka, release kereta | ____________________ | ____________________ |
| Travel time: endpoint, arah dan sampel ulang | ____________________ | ____________________ |
| Antrean: referensi meter, count, tail, batas pandang | ____________________ | ____________________ |
| Hambatan samping, insiden dan blockage | ____________________ | ____________________ |
| Geometri lajur, stop line, storage dan clearance | ____________________ | ____________________ |
| Kepemilikan, penyimpanan, akses dan retensi data | ____________________ | ____________________ |
| QC, hitung ganda dan adjudikasi independen | ____________________ | ____________________ |
| Coverage lengkap, missing, censoring dan uncertainty | ____________________ | ____________________ |
| Sampel kalibrasi dan holdout validasi terpisah | ____________________ | ____________________ |
| Kriteria kelengkapan dan jadwal tinjau | ____________________ | ____________________ |

## Kriteria awal kelengkapan

Catat tanggal, lokasi/arah, metode, izin, jam tersinkronisasi, interval lengkap, kelas/gerakan, sumber/hash dan peninjau. Missing bukan nol. Partial count bukan volume interval lengkap. Antrean count bukan meter. Batas pandang yang terlampaui diberi censoring. Simpan insiden dan perubahan metode. Jangan memakai observasi kalibrasi sebagai validasi independen.

Workbench M08.5: PARTIAL_BROWSER_ACCEPTANCE_PENDING. Bahan ini membantu diskusi/form preview dan belum mengesahkan workbench untuk survei produksi.

Persetujuan metode/lokasi oleh peserta (jika diberikan): ____________________
Perubahan yang perlu ditinjau lagi: ________________________________________
'''
 (OUT/'M11_FIELD_MEETING_CHECKLIST.md').write_text(checklist,encoding='utf-8')
 discussion='# Panduan diskusi teknis\n\n'+ '\n\n'.join(f'## {i+1}. {s[0]}\n\n{s[4]}\n\nCatat koreksi, bukti yang diperlukan, penanggung jawab dan keputusan pada lembar lapangan. Pertahankan perbedaan antara asumsi, geometri sumber dan observasi.' for i,s in enumerate(SCENES))+'\n\nTidak ada keputusan konstruksi atau pengesahan legalitas yang diambil otomatis oleh simulator.\n'
 (OUT/'M11_PANDUAN_DISKUSI_TEKNIS.md').write_text(discussion,encoding='utf-8')
 appendix='# Lampiran teknis Gedangan\n\n'+d['scientific_status']+'\n\n'+d['baseline_status']+'\n\n## Metode\n\nJaringan SUMO/OSM dan permissions M04.5, pemisahan arterial/frontage, one-way/restrictions, railway M05.1 dipertahankan. M11 memakai build M10 tanpa membangun frontend baru. FCD 0,5 s dan state kontrol 1 s memakai clock yang diuji (+0,5 s FCD terhadap TraCI). SUMO 1.28.0 telah menjalankan run M08 yang diekspor M09. Tidak ada run baru, kalibrasi atau data lapangan yang dibuat pada M11.\n\n## Definisi dan censoring\n\nRequested = routable + failed routes. Routable = departed + not departed. Departed = arrived + running at end. NOT ARRIVED BY SIMULATION END = requested − arrived. Loaded/departed dibedakan. Completion memakai arrived/requested dalam 2100 s. Waiting mean departed termasuk unfinished trips adalah diagnostik bersyarat. Throughput model bukan kapasitas jalan terukur.\n\n## Run yang tersedia\n\n| Run ID | Tahun | Growth | Skenario | Requested | Arrived | Running | Gagal rute | Belum berangkat |\n|---|---|---|---|---|---|---|---|---|\n'
 for r in a['rows']:
  m=r['metrics'];appendix+=f'| {r["run_id"]} | {r["year"]} | {r["demand_type"]} | {r["scenario"]} | {m["requested"]} | {m["arrived"]} | {m["running_at_end"]} | {m["failed_routes"]} | {m["not_departed"]} |\n'
 appendix+='\nSeluruh baris: SIMULATED_RESULT / demand provisional, seed 42, horizon 2100 s. Provenance per-run, hash network/cohort/index, units dan definisi tersimpan pada M11_NUMERIC_DATA_AUDIT.json. Sumber manifest M09 dan index cache asli diverifikasi sebelum launcher siap.\n\n## Pertumbuhan dan parity\n\nN_y=N_2026 × produk(1+r_t) per kelas dan OD, dengan alokasi integer M07. Rate 2027–2040 sementara. FINAL_RATE_SUBSTITUTION mengganti laju dasar untuk override OD, tidak menambahkannya. Semua aturan LOW/REFERENCE/HIGH disalin sebagai data sumber dalam audit, bukan diedit. Before/after harus cocok tahun, growth, seed, cohort dan horizon, dengan delta jaringan dijelaskan manifest.\n\n## Geometri, observasi dan kalibrasi\n\nSource short/internal lanes, angular junctions, rail/stop-line alignment dan clearance memiliki ketidakpastian. Dekorasi 3D tidak menyatakan footprint aktual. Calon detector/lokasi survei belum disahkan. M06 empirical gate disabled karena observasi 2026 terverifikasi tidak tersedia. Pipeline yang diperlukan: raw evidence dan provenance, normalisasi/M06 import, QC/coverage/missing, training calibration, holdout validation independen, sensitivity dan review. M08.5 belum lolos penerimaan browser, sehingga tidak dipromosikan menjadi field production-ready.\n\n## Infrastruktur konseptual\n\nS05 structurally blocked. S06/S07 CONCEPT ONLY, tidak memiliki valid derivative simulation network untuk klaim efektivitas. Alignment, ruang, utilitas, izin, keselamatan, clearance dan swept path masih memerlukan pekerjaan engineering. Tidak ada kendaraan yang dipaksa melalui ruas terlarang atau konsep.\n'
 (OUT/'M11_LAMPIRAN_TEKNIS.md').write_text(appendix,encoding='utf-8')
 qa=[('Apakah ini kondisi lalu lintas aktual Gedangan?','Tidak ada observasi lapangan terverifikasi dalam dataset proyek. Yang aktual adalah rekaman keluaran SUMO dengan demand/asumsi model.'),('Apakah 2040 merupakan prediksi resmi?','Angka 2040 adalah skenario pertumbuhan M07 yang belum tervalidasi, bukan prakiraan resmi.'),('Apakah S01 pasti memperbaiki kondisi?','Tidak. Pada pasangan 2040 HIGH jumlah tiba turun dari 356 menjadi 328 dari 500 requested. Baca unfinished trips dan trade-off OD bersama.'),('Mengapa requested tidak sama dengan arrived?','Requested mencakup gagal rute, belum berangkat dan masih berjalan saat horizon berakhir. Keempat kategori dihitung terpisah.'),('Apakah warna overlay adalah antrean terukur?','Stopped dan occupied length berasal dari sampel FCD. Tidak sama dengan panjang antrean meter, detector occupancy atau sebab kemacetan.'),('Apakah flyover/underpass siap konstruksi?','S06/S07 masih konseptual. Belum ada alignment, clearance, swept path atau jaringan turunan simulasi valid.'),('Apakah titik survei sudah disetujui?','Belum. Tujuh calon titik M06/M08.5 memerlukan reconnaissance, izin dan review posisi aman/coverage.'),('Apakah workbench siap dipakai produksi?','Status M08.5 masih PARTIAL_BROWSER_ACCEPTANCE_PENDING. Gunakan bahan diskusi/form preview, bukan mengklaim kesiapan survei produksi.'),('Apakah demonstrasi perlu internet?','Build, gambar, video, deck dan cache tersedia lokal. Layanan 3D memakai loopback. PDF/HTML/video dapat menjadi cadangan saat layanan berhenti.'),('Apa keputusan yang diminta pada rapat?','Prioritas observasi, izin/lokasi, metode, PIC dan kriteria QC/validasi. Bukan persetujuan proyek konstruksi atau pengesahan efektivitas.')]
 (OUT/'M11_TANYA_JAWAB.md').write_text('# Tanya jawab presenter\n\n'+'\n\n'.join('## '+q+'\n\n'+answer for q,answer in qa),encoding='utf-8')
 print('Scripts, discussion, appendix, Q&A and offline entry/deck generated')
if __name__=='__main__':main()
